-- G'26 Voluntários: criação completa do banco de DEMONSTRAÇÃO (migrações 0001 a 0005 + semente fictícia).
-- Colar inteiro no SQL Editor do Supabase e executar uma única vez, em um banco vazio.

-- ===== supabase/migrations/0001_init_m0.sql =====
-- G'26 Voluntários — M0
-- Subconjunto do modelo de dados (seção 6) necessário para login de
-- voluntário/ADM e para o modo demonstração.
--
-- Convenções: chaves uuid, created_at/updated_at em timestamptz,
-- exclusão lógica via coluna "active" quando fizer sentido.
--
-- Segurança (seção 2 e 12): RLS habilitado em TODAS as tabelas, SEM
-- políticas para os papéis anon/authenticated. O acesso só acontece pelo
-- servidor, usando a service role (que ignora RLS por padrão no
-- Supabase). Isso garante que nada vaza mesmo se uma chave pública for
-- exposta por engano.

create extension if not exists "pgcrypto";

-- ---------------------------------------------------------------------
-- teams
-- ---------------------------------------------------------------------
create table if not exists teams (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  group_name text,
  sort integer not null default 0,
  is_mock boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table teams is 'Equipes de voluntários (ex.: Acolhida, Check In, Chapelaria).';
comment on column teams.is_mock is 'Marca dados de semente do modo demonstração (seção 11).';

-- ---------------------------------------------------------------------
-- volunteers
-- ---------------------------------------------------------------------
create table if not exists volunteers (
  id uuid primary key default gen_random_uuid(),
  full_name text not null,
  search_name text not null, -- nome normalizado (sem acento, minúsculo) para busca
  team_id uuid references teams(id) on delete set null,
  is_leader boolean not null default false,
  photo_path text,
  pin_hash text, -- hash argon2id da credencial (4 últimos dígitos do CPF + DDMM)
  birth_dm text, -- DDMM, apenas para exibição/depuração administrativa; nunca é a credencial em si
  diet_notes text,
  login_locked_until timestamptz,
  active boolean not null default true,
  is_mock boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table volunteers is 'Voluntários cadastrados a partir da ficha de inscrição (seção 5.1). Nunca armazena CPF/RG em texto.';
comment on column volunteers.pin_hash is 'Hash argon2id da credencial; a credencial em texto nunca é armazenada.';

create index if not exists idx_volunteers_search_name on volunteers (search_name);
create index if not exists idx_volunteers_team_id on volunteers (team_id);

-- ---------------------------------------------------------------------
-- volunteers_private — CPF/RG criptografados, tabela separada (seção 12)
-- ---------------------------------------------------------------------
create table if not exists volunteers_private (
  volunteer_id uuid primary key references volunteers(id) on delete cascade,
  cpf_enc text not null, -- criptografado na aplicação (AES-GCM), nunca em texto puro
  rg_enc text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table volunteers_private is 'CPF e RG, sempre criptografados pela aplicação antes de gravar. Lida só em rotas de servidor dedicadas.';

-- ---------------------------------------------------------------------
-- admin_accounts
-- ---------------------------------------------------------------------
create table if not exists admin_accounts (
  volunteer_id uuid primary key references volunteers(id) on delete cascade,
  password_hash text not null,
  can_manage_radios boolean not null default false,
  locked_until timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table admin_accounts is 'Credencial individual de ADM (segunda barreira da Área do QG, seção 5.3).';

-- ---------------------------------------------------------------------
-- login_attempts
-- ---------------------------------------------------------------------
create table if not exists login_attempts (
  id uuid primary key default gen_random_uuid(),
  volunteer_id uuid references volunteers(id) on delete cascade,
  kind text not null default 'volunteer' check (kind in ('volunteer', 'admin')),
  ip_hash text, -- hash do IP, nunca o IP em texto
  ok boolean not null,
  created_at timestamptz not null default now()
);

comment on table login_attempts is 'Registro de tentativas de login, sem gravar o que foi digitado (seção 5.2).';

create index if not exists idx_login_attempts_volunteer_created on login_attempts (volunteer_id, created_at desc);
create index if not exists idx_login_attempts_ip_created on login_attempts (ip_hash, created_at desc);

-- ---------------------------------------------------------------------
-- app_settings
-- ---------------------------------------------------------------------
create table if not exists app_settings (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now()
);

comment on table app_settings is 'Configurações globais: demo_mode, simulated_now (demonstração/ADM).';

on conflict (key) do nothing;

-- ---------------------------------------------------------------------
-- audit_log
-- ---------------------------------------------------------------------
create table if not exists audit_log (
  id uuid primary key default gen_random_uuid(),
  actor_id uuid references volunteers(id) on delete set null,
  action text not null,
  entity text not null,
  entity_id uuid,
  details jsonb not null default '{}'::jsonb, -- NUNCA colocar dados pessoais aqui
  created_at timestamptz not null default now()
);

comment on table audit_log is 'Trilha de auditoria das ações de ADM. "details" nunca deve conter dados pessoais.';

-- ---------------------------------------------------------------------
-- RLS: habilitado em tudo, sem políticas para anon/authenticated.
-- Apenas a service role (usada só no servidor) tem acesso.
-- ---------------------------------------------------------------------
alter table teams enable row level security;
alter table volunteers enable row level security;
alter table volunteers_private enable row level security;
alter table admin_accounts enable row level security;
alter table login_attempts enable row level security;
alter table app_settings enable row level security;
alter table audit_log enable row level security;

-- Nenhuma política é criada de propósito: sem policy, anon/authenticated
-- não leem nem escrevem nada. A service role ignora RLS por padrão.

-- ===== supabase/migrations/0002_m1_meals.sql =====
-- G'26 Voluntários — M1: refeições e check-in (seções 6 e 10)

-- Perfil da conta da Área do QG: 'adm' (QG completo) ou 'radios' (gestor de rádios).
alter table admin_accounts
  add column if not exists role text not null default 'adm' check (role in ('adm', 'radios'));

create table if not exists event_days (
  id uuid primary key default gen_random_uuid(),
  date date not null unique,
  label text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists meals (
  id uuid primary key default gen_random_uuid(),
  day_id uuid not null references event_days(id) on delete cascade,
  kind text not null check (kind in ('cafe', 'almoco', 'lanche', 'janta')),
  label text not null,
  starts_at timestamptz not null,
  ends_at timestamptz not null check (ends_at > starts_at),
  menu_text text,
  total_prepared integer not null default 0 check (total_prepared >= 0),
  is_mock boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (day_id, kind)
);

create table if not exists team_meal_windows (
  team_id uuid not null references teams(id) on delete cascade,
  meal_id uuid not null references meals(id) on delete cascade,
  starts_at timestamptz not null,
  ends_at timestamptz not null check (ends_at > starts_at),
  is_mock boolean not null default false,
  primary key (team_id, meal_id)
);

create table if not exists meal_checkins (
  id uuid primary key default gen_random_uuid(),
  volunteer_id uuid not null references volunteers(id) on delete cascade,
  meal_id uuid not null references meals(id) on delete cascade,
  method text not null check (method in ('qr', 'search')),
  checked_by uuid references volunteers(id) on delete set null,
  is_mock boolean not null default false,
  created_at timestamptz not null default now(),
  -- Uma refeição de cada tipo por voluntário: garantido no banco (princípio 5, critério 1).
  constraint meal_checkins_one_per_meal unique (volunteer_id, meal_id)
);

create index if not exists idx_meal_checkins_meal on meal_checkins (meal_id);

alter table event_days enable row level security;
alter table meals enable row level security;
alter table team_meal_windows enable row level security;
alter table meal_checkins enable row level security;

-- ===== supabase/migrations/0003_m2_radios.sql =====
-- G'26 Voluntários — M2: rádios (seção 9)

create table if not exists radios (
  id uuid primary key default gen_random_uuid(),
  number integer not null unique check (number > 0),
  status text not null default 'ok' check (status in ('ok', 'defeito', 'perdido')),
  notes text,
  is_mock boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists radio_checkouts (
  id uuid primary key default gen_random_uuid(),
  radio_id uuid not null references radios(id) on delete cascade,
  volunteer_id uuid not null references volunteers(id) on delete cascade,
  checked_out_at timestamptz not null default now(),
  checked_out_by uuid references volunteers(id) on delete set null,
  signature_path text, -- caminho no bucket privado "signatures"
  returned_at timestamptz,
  returned_by uuid references volunteers(id) on delete set null, -- operador que registrou
  returned_by_volunteer_id uuid references volunteers(id) on delete set null, -- quem entregou o rádio
  battery_state text check (battery_state in ('carregado', 'parcial', 'descarregado')),
  condition text check (condition in ('ok', 'defeito')),
  is_mock boolean not null default false,
  created_at timestamptz not null default now(),
  check ((returned_at is null) = (battery_state is null and condition is null))
);

-- Um rádio não pode ter duas retiradas abertas ao mesmo tempo (critério 10).
create unique index if not exists radio_checkouts_one_open_per_radio
  on radio_checkouts (radio_id) where returned_at is null;

create index if not exists idx_radio_checkouts_volunteer on radio_checkouts (volunteer_id);

alter table radios enable row level security;
alter table radio_checkouts enable row level security;

-- Bucket privado para as assinaturas (acesso só por URL assinada de curta duração).
values ('signatures', 'signatures', false)
on conflict (id) do nothing;

-- ===== supabase/migrations/0004_m3_schedule_map.sql =====
-- G'26 Voluntários — M3: cronograma, locais do mapa e escala por equipe (seções 6 e 7)

create table if not exists locations (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  kind text not null check (kind in ('refeitorio', 'banheiro', 'enfermaria', 'qg', 'palco', 'acolhida', 'loja', 'kids', 'portao', 'servico', 'oracao')),
  description text,
  map_x numeric(5,2) not null check (map_x between 0 and 100), -- posição em % da largura do mapa
  map_y numeric(5,2) not null check (map_y between 0 and 100), -- posição em % da altura do mapa
  is_mock boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists schedule_items (
  id uuid primary key default gen_random_uuid(),
  day_id uuid not null references event_days(id) on delete cascade,
  session_label text not null,
  starts_at timestamptz not null,
  ends_at timestamptz not null check (ends_at > starts_at),
  title text not null,
  performer text,
  kind text not null check (kind in ('portoes', 'worship', 'pregacao', 'short', 'pitch', 'prayer', 'intervalo', 'missa', 'comunicacao', 'outro')),
  is_mock boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_schedule_items_starts on schedule_items (starts_at);

create table if not exists team_schedule (
  id uuid primary key default gen_random_uuid(),
  team_id uuid not null references teams(id) on delete cascade,
  day_id uuid not null references event_days(id) on delete cascade,
  starts_at timestamptz not null,
  ends_at timestamptz not null check (ends_at > starts_at),
  location_id uuid references locations(id) on delete set null,
  activity text not null,
  is_break boolean not null default false, -- intervalo ou refeição
  is_mock boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_team_schedule_team_starts on team_schedule (team_id, starts_at);

alter table locations enable row level security;
alter table schedule_items enable row level security;
alter table team_schedule enable row level security;

-- ===== supabase/migrations/0005_m4_praise.sql =====
-- G'26 Voluntários — M4: elogios anônimos, janelas e pins (seções 6 e 8)

create table if not exists praise_windows (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  is_open boolean not null default false,
  opened_at timestamptz,
  closed_at timestamptz,
  opened_by uuid references volunteers(id) on delete set null,
  is_mock boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- No máximo uma janela aberta por vez.
create unique index if not exists praise_windows_single_open on praise_windows ((true)) where is_open;

create table if not exists praises (
  id uuid primary key default gen_random_uuid(),
  window_id uuid not null references praise_windows(id) on delete cascade,
  -- O remetente existe SÓ para aplicar a unicidade. Nenhuma rota, visão ou tela o expõe.
  sender_id uuid not null references volunteers(id) on delete cascade,
  receiver_id uuid not null references volunteers(id) on delete cascade,
  trait text not null check (trait in ('feliz', 'facilitador', 'por_inteiro')),
  is_mock boolean not null default false,
  created_at timestamptz not null default now(),
  constraint praises_one_per_trait_per_window unique (window_id, sender_id, receiver_id, trait),
  constraint praises_no_self check (sender_id <> receiver_id)
);

create index if not exists idx_praises_window_receiver on praises (window_id, receiver_id);

-- Elogio só entra (ou sai) com a janela aberta, mesmo chamando o banco direto (critério 6).
create or replace function praises_require_open_window() returns trigger
language plpgsql as $$
declare
  win uuid := coalesce(new.window_id, old.window_id);
begin
  if not exists (select 1 from praise_windows w where w.id = win and w.is_open) then
    raise exception 'janela de elogios fechada' using errcode = 'P0001';
  end if;
  return coalesce(new, old);
end $$;

drop trigger if exists trg_praises_open_window on praises;
create trigger trg_praises_open_window
  before insert or update or delete on praises
  for each row execute function praises_require_open_window();

-- Leitura agregada: só totais por pessoa, característica e janela. Sem remetente.
create or replace view praise_totals_by_window as
  select window_id, receiver_id, trait, count(*)::int as total
  from praises
  group by window_id, receiver_id, trait;

-- Alerta informativo de reciprocidade: devolve só um número, nunca quem.
create or replace function praise_reciprocal_pairs(p_window uuid) returns integer
language sql stable as $$
  select count(*)::int from (
    select distinct least(a.sender_id, a.receiver_id), greatest(a.sender_id, a.receiver_id)
    from praises a
    join praises b on b.window_id = a.window_id and b.sender_id = a.receiver_id and b.receiver_id = a.sender_id
    where a.window_id = p_window
  ) pairs;
$$;

create table if not exists pin_awards (
  id uuid primary key default gen_random_uuid(),
  volunteer_id uuid not null references volunteers(id) on delete cascade,
  trait text not null check (trait in ('feliz', 'facilitador', 'por_inteiro')),
  awarded_by uuid references volunteers(id) on delete set null,
  awarded_at timestamptz not null default now(),
  delivered_at timestamptz,
  is_mock boolean not null default false,
  -- Um mesmo pin não é concedido duas vezes à mesma pessoa.
  constraint pin_awards_once unique (volunteer_id, trait)
);

alter table volunteers add column if not exists privacy_accepted_at timestamptz;


alter table praise_windows enable row level security;
alter table praises enable row level security;
alter table pin_awards enable row level security;
-- A visão herda a proteção: sem política para anon/authenticated, nada é lido de fora do servidor.
revoke all on praise_totals_by_window from anon, authenticated;
revoke all on function praise_reciprocal_pairs(uuid) from anon, authenticated, public;

